// Precios de lista en USD, región sa-east-1 (São Paulo), a pedido, PostgreSQL.
// Fuente: lista de precios de AWS publicada el 13-11-2026. Supabase: página de precios leída el 16-11-2026.
const H = 730;                       // horas de un mes promedio (365 días * 24 / 12)
const P = {
  micro:  { simple: 0.034, multi: 0.069 },   // RDS db.t4g.micro, USD por hora
  small:  { simple: 0.069, multi: 0.137 },   // RDS db.t4g.small
  gp3:    { simple: 0.219, multi: 0.438 },   // RDS almacenamiento gp3, USD por GB-mes
  acu: 0.25, auroraGB: 0.19,                 // Aurora Serverless v2: USD por ACU-hora; Aurora: USD por GB-mes consumido
  supabasePro: 25,                           // Supabase Pro: incluye 10 USD de crédito de cómputo (una Micro) y 8 GB de disco
};
const GB = 20;
const usd = (n) => 'USD ' + n.toFixed(2).padStart(7);
const filas = [
  ['RDS micro, una zona',            P.micro.simple * H + P.gp3.simple * GB],
  ['RDS micro, Multi-AZ',            P.micro.multi * H + P.gp3.multi * GB],
  ['RDS small, Multi-AZ',            P.small.multi * H + P.gp3.multi * GB],
  ['Aurora SL v2, 2 ACU fijas 24 h', 2 * P.acu * H + P.auroraGB * GB],
  ['Aurora SL v2, 1 ACU, 6 h al día', 1 * P.acu * 6 * (H / 24) + P.auroraGB * GB],
  ['Supabase Pro (1 proyecto Micro)', P.supabasePro],
];
console.log(`Base de ${GB} GB, mes de ${H} horas`);
for (const [n, v] of filas) console.log(n.padEnd(34), usd(v));
console.log('No incluye: tráfico de salida, copias de seguridad adicionales, cobros por I/O de Aurora ni impuestos.');
